head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setGridStyle]<br/>GridView 컴포넌트의 전체 구조 정의를 JSON 형식의 문자열로 설정합니다.",
    "validation" : [
        "doc(필수) 파라미터로 GridView 의 전체 구조를 JSON 형식의 문자열로 설정합니다.",
        "기존 GridView 정의를 완전히 제거하고 파라미터로 새로운 GridView 정의를 설정하는 구조적 재생성 메소드입니다.",
        "구조만 정의하며 데이터는 정의하지 않습니다.",
        "유효하지 않은 문자열 설정 시 메소드가 실행되지 않고 기존 GridView 를 그대로 유지합니다.",
    ]
}



scwin.gVar = { "docB" : "" };



scwin.onpageload = function () {
    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // 초기 구조 A(3컬럼: 사번/이름/부서)에서 유효한 전체 구조 JSON 문자열을 getCurrentGridStyle 로 확보한 뒤,
    //  구조 B(4컬럼: 사원번호/성명/소속부서/직급, 헤더·너비 변경)로 수정하여 setGridStyle 에 넘길 doc 로 준비
    let styleObj = JSON.parse(target1.getCurrentGridStyle());
    let headerRow = styleObj.E.find(function (e) { return e.N === "w2:header"; }).E[0];
    let bodyRow = styleObj.E.find(function (e) { return e.N === "w2:gBody"; }).E[0];

    // 헤더 라벨 변경 (완전 재생성 확인용)
    headerRow.E[0].A.value = "사원번호";
    headerRow.E[1].A.value = "성명";
    headerRow.E[2].A.value = "소속부서";
    // 컬럼 너비 변경
    headerRow.E[0].A.width = 100;
    bodyRow.E[0].A.width = 100;
    // 4번째 컬럼(직급) 추가 → dataList 에는 없는 신규 구조 컬럼(데이터는 JSON 에 정의되지 않음)
    headerRow.E.push({ T: 1, N: "w2:column", A: { width: 110, style: "", inputType: "text", id: "hcol4", value: "직급" } });
    bodyRow.E.push({ T: 1, N: "w2:column", A: { width: 110, style: "", inputType: "text", id: "col4", displayType: "label" } });
    styleObj.A.columnOrder = [0, 1, 2, 3];

    scwin.gVar.docB = JSON.stringify(styleObj);
};



// setGridStyle 후 재생성된 grid 객체를 재획득 (재생성으로 기존 참조가 무효화될 수 있음)
scwin.getGrid = function () {
    return $p.getComponentById("mf_target1");
};



// [setGridStyle 구조 B] getCurrentGridStyle 로 확보한 유효 JSON(doc)으로 GridView 전체 구조 재생성
scwin.btn_setGridStyleB_onclick = function () {
    target1.setGridStyle(scwin.gVar.docB);

    let g = scwin.getGrid();
    let headers = [];
    for (var i = 0; i < g.getColumnCount(); i++) {
        headers.push(g.getHeaderValue("hcol" + (i + 1)));
    }
    wf_body_bottom.getObj("scwin").setReturnValue("[재생성 후 컬럼 수] " + g.getColumnCount());
    wf_body_bottom.getObj("scwin").setReturnValue("[재생성 후 헤더] " + headers.join(", "));
    // 구조만 정의·데이터 미정의 : dataList 에 없는 신규 직급 컬럼(col4)은 데이터가 비어있음
    wf_body_bottom.getObj("scwin").setReturnValue("[구조만 정의·데이터 미정의] 신규 직급 컬럼(col4) 첫 행 값 = '" + g.getCellData(0, "col4") + "'");
};



// [setGridStyle 잘못된 문자열] 유효하지 않은 문자열 → 메소드 미실행, 기존 GridView 유지
scwin.btn_setGridStyleInvalid_onclick = function () {
    let g = scwin.getGrid();
    let beforeCol = g.getColumnCount();

    // 유효하지 않은(파싱 불가) 구조 문자열 → 메소드 미실행, 기존 GridView 유지
    g.setGridStyle('{"N":"w2:gridView" 유효하지 않은 구조 문자열}');

    let g2 = scwin.getGrid();
    let afterCol = g2.getColumnCount();
    let afterHeaders = [];
    for (var j = 0; j < afterCol; j++) {
        afterHeaders.push(g2.getHeaderValue("hcol" + (j + 1)));
    }
    wf_body_bottom.getObj("scwin").setReturnValue("[잘못된 문자열 후 기존 구조 유지] 컬럼 수 " + beforeCol + " -> " + afterCol + " / 헤더 " + afterHeaders.join(", "));
};
